def forward(groups):
    value = float(groups[0])
    unit = groups[2]
    multiplier = {'B': 1, 'KB': 1024, 'MB': 1024**2}[unit]
    stored_value = int(round(value * multiplier))
    return {'stored': [stored_value], 'layout': []}

def inverse(record):
    bytes = record['stored'][0]
    if bytes >= 1024**2:
        value = bytes / 1024**2
        unit = 'MB'
    elif bytes >= 1024:
        value = bytes / 1024
        unit = 'KB'
    else:
        value = bytes
        unit = 'B'
    return f"{value:.1f} {unit}"
